MAX_COL = 17


def norm_str(v):
    if v is None:
        return ""
    if isinstance(v, str):
        return v.strip()
    return str(v).strip()


def clean_value(v, col):
    if isinstance(v, str):
        v = v.strip()
        if v == "":
            return None

        # If a date-like string appears in the Date column, make it a real datetime.
        if col == 13:
            try:
                dt = datetime.fromisoformat(v)
                if dt.tzinfo is not None:
                    dt = dt.replace(tzinfo=None)
                return dt
            except ValueError:
                pass

    return v


matches = []

for r in range(1, MAX_ROW + 1):
    a = vws.cell(r, 1).value
    b = vws.cell(r, 2).value
    c = vws.cell(r, 3).value

    is_match = (
        r > 1
        and norm_str(a) == "Government"
        and norm_str(b) == "Germany"
        and norm_str(c) == "Carretera"
    )

    for col in range(1, MAX_COL + 1):
        v = vws.cell(r, col).value
        v = clean_value(v, col)

        if col == 17 and is_match:
            v = "Volkswagen"

        cell = ws.cell(r, col)
        if MergedCell is None or not isinstance(cell, MergedCell):
            cell.value = v

    if is_match:
        matches.append(r)

wb.save(OUT)

